questions.code:
h1      { color: red; }
.heading { color: blue; }
#title  { color: green; }

a:link    { color: black; }
a:visited { color: yellow; }
a:active  { color: red; }

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.page {
  display: grid;
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
}

nav {
  ul { margin: 0; }
  li { display: inline-block; }
}
